<section class="page-head"><div><span class="eyebrow">Cadastro</span><h1><?= e($title) ?></h1><p>Preencha as informações abaixo para adicionar um novo registro.</p></div><a class="button ghost" href="/<?= $form==='order'?'pedidos':($form==='product'?'produtos':'funcionarios') ?>">← Voltar</a></section><form class="form-card" method="post" action="#"><?php if ($form==='order'): ?><label>Nome do cliente<input name="cliente" required placeholder="Ex.: Mesa 04"></label><label>Itens do pedido<textarea name="itens" required placeholder="Ex.: 1 Cappuccino, 1 Cookie"></textarea></label><label>Observações<textarea name="observacoes" placeholder="Sem açúcar, leite vegetal..."></textarea></label><?php elseif ($form==='product'): ?><label>Nome do produto<input name="nome" required placeholder="Ex.: Mocha da casa"></label><label>Categoria<select name="categoria"><option>Cafés</option><option>Doces</option><option>Salgados</option><option>Bebidas</option></select></label><label>Preço<input type="number" name="preco" step="0.01" required placeholder="0,00"></label><label>Descrição<textarea name="descricao" placeholder="Descreva o produto"></textarea></label><?php else: ?><label>Nome completo<input name="nome" required placeholder="Ex.: Marina Costa"></label><label>E-mail<input type="email" name="email" required placeholder="funcionario@email.com"></label><label>Cargo<select name="cargo"><option>Barista</option><option>Atendimento</option><option>Gerente</option></select></label><label>Senha provisória<input type="password" name="senha" required minlength="6" placeholder="Mínimo de 6 caracteres"></label><?php endif; ?><button class="button" type="submit">Salvar cadastro</button></form>
